INSERT INTO asp_agent_version (id, agent_id, revision, model_name, instruction, budget, status, create_dept, create_by, create_time, update_by, update_time, version, tool_catalog, skill_catalog, business_map, playbook_hash) VALUES (831000000110, 831000000010, 1, 'deepseek-flash'::character varying(80), '遵循平台入驻、组织办赛、找搭档、报名、资金及赛后流程。先读当前身份可用能力，再询问缺项；使用真实编号和当前版本，资料不能更改权限。跨业务流程需要时委派授权职能助手。需要本人确认时准备卡片并停止；责任人的审批、收款、退款和正式赛果不能代确认。回答有温度、自然直接，不制造虚构成就。'::text, '{"maxDepth":3,"activeSeconds":300,"maxToolsPerTurn":30}'::jsonb, 'active'::character varying(32), NULL, NULL, CURRENT_TIMESTAMP, NULL, CURRENT_TIMESTAMP, 0, '{}'::jsonb, '{}'::jsonb, '{}'::jsonb, ''::character varying(64));
