":["联系人","时间地点和声明","本人确认当前版本"],"dependsOn":["event-fees"],"capabilities":["event.publish"]},{"code":"event-materials","path":"/org-desk/workspace/{eventId}?task=materials","title":"准备策划、脚本和宣传","checks":["文稿仍是工作草稿","封面明确选择后保存"],"dependsOn":["event-draft"],"capabilities":["event.material.save","event.material.generate","event.cover.save"]}],"title":"办一场赛事","actors":["organizer"]},{"code":"join-and-team","goal":"找到合适赛事，建立本场房间并由成员本人完成加入与准备","steps":[{"code":"room-discovery","path":"/portal/rooms","title":"查看本场集结","questions":["已经有想参加的赛事了吗？","想参加单打，还是找个双打搭档？"],"capabilities":["room.query"]},{"code":"room-assemble","path":"/portal/rooms","title":"建房、招募或匹配","checks":["房主计入人数","匹配邀请由本人接受"],"dependsOn":["room-discovery"],"capabilities":["room.create","room.recruit","room.apply","room.match"]},{"code":"room-ready","path":"/portal/rooms","title":"各自补资料并准备","checks":["成员本人确认","本场名单与长期队伍分开"],"dependsOn":["room-assemble"],"capabilities":["room.ready","room.prepare"]}],"title":"找赛事与队友","actors":["platform"]},{"code":"register-event","goal":"补齐成员资料后核对整单并正式报名，分别跟进付款与资格","steps":[{"code":"registration-draft","path":"/portal/registration","title":"查看或建立本人报名","questions":["报名哪一场赛事和项目？","这次是个人参赛还是和队友一起？"],"capabilities":["registration.mine","registration.create"]},{"code":"registration-submit","path":"/portal/registration","title":"核对名单、规则与费用","checks":["本人资料与声明","整单名额和当前版本","本人明确确认"],"dependsOn":["registration-draft"],"capabilities":["registration.submit"]}],"title":"完成报名","actors":["platform"]},{"code":"after-event","goal":"查看正式赛果、证明与成长，并接续退款或投诉责任","steps":[{"code":"aftercare-progress","path":"/org-desk/workspace/{eventId}?task=closure","title":"查看赛后收尾","actors":["organizer"],"checks":["比赛状态","资金责任","未完投诉"],"capabilities":["event.closure"]},{"code":"aftercare-growth","path":"/portal/growth","title":"查看本人运动成长","actors":["platform"],"checks":["成长来源与真实事实","本人选择佩戴称号"],"capabilities":["growth.card","growth.equip"]},{"code":"aftercare-issue","path":"/portal/issues","title":"提交或接续问题","actors":["platform"],"checks":["问题编号","实际责任人与回复"],"capabilities":["complaint.submit","complaint.reply"]}],"title":"赛后与问题处理","actors":["platform","organizer","government"]},{"code":"government-service","goal":"按已指定的管理范围审核、协调与恢复资格","steps":[{"code":"government-scope","title":"核对主办方资格","checks":["明确分配的主办方范围","材料和协调责任"],"questions":["要处理哪家主办方？"],"capabilities":["government.qualify"]},{"code":"government-issue","path":"/government/issues","title":"协调具体问题","checks":["责任人","历史回复和当前状态"],"questions":["要接续哪一个问题编号？"],"capabilities":["complaint.handle","complaint.reply"]}],"title":"主办方审核与协调","actors":["government","admin"]}],"title":"赛事服务流程","schemaVersion":1}'::jsonb, '47c5c18b417525487cf9efad12cb1158750665080a57db61896f56d1013ab3ce'::character varying(64));
INSERT INTO asp_agent_version (id, agent_id, revision, model_name, instruction, budget, status, create_dept, create_by, create_time, update_by, update_time, version, tool_catalog, skill_catalog, business_map, playbook_hash) VALUES (831000000212, 831000000012, 2, 'deepseek-flash'::character varying(80), '先理解用户真正想办成什么，按本次锁定的技能目录、业务地图和实际能力带着用户推进。先查sports_playbook与当前能力，区分页面可办与助手可办；能从授权事实取得的资料不重复追问。一次优先处理一个最小阻塞项，最多补问三个必要问题，说明为什么需要与补完后会做什么。对新人自然欢迎，对担心和失败先接住具体困难，不夸大成就、不空泛鼓励。引用材料的真实位置和覆盖范围；冲突明确补问，不能猜编号、日期、费用或政府背书。缺权限或能力未开放时说明实际边界，给本人能继续的人工入口。涉及发布、报名及重要变更，用当前版本准备确认卡后停下；真实资金、政府审核、正式结果和荣誉由责任人办理。成功只依据真实业务回执。用户可見业务步骤、补充与回执需要可恢复；不输出或保存隐藏思考、凭据或未经授权的材料。最终答复使用reply与blocks的JSON对象，提供引导、必要问题、待办清单及已登记的下一步入口，避免演示口号和技术配置术语。'::text, '{"maxDepth":3,"activeSeconds":300,"maxToolsPerTurn":30}'::jsonb, 'active'::character varying(32), NULL, NULL, CURRENT_TIMESTAMP, NULL, CURRENT_TIMESTAMP, 0, '{"entries":[{"name":"sports_playbook","usage":"开始办理及授权变化后先读取；这是引导资料，不能扩大操作权限","channel":"controlled-agent-run","purpose":"读取本次运行锁定的技能与业务地图，以及当前角色实际可用的页面/Agent能力","arguments":{},"agentAllowed":true},{"name":"sports_capabilities","usage":"选择实际工具动作之前读取，不把页面能力当Agent授权","channel":"controlled-agent-run","purpose":"查询本人当前已开放的Agent能力","arguments":{},"agentAllowed":true},{"name":"sports_preview","usage":"编号来自本人已授权查询或本人明确提供，不猜编号","channel":"controlled-agent-run","purpose":"核对真实对象、缺项和当前版本","arguments":{"code":"registered-action-code","inputJson":"JSON object encoded as string"},"agentAllowed":true},{"name":"sports_execute","usage":"同一办理断线重试沿用原参数与原编号；资金、审核与正式结果不得代确认","channel":"controlled-agent-run","purpose":"执行已开放、无需本人确认的授权动作","arguments":{"code":"registered-action-code","inputJson":"JSON object encoded as string","requestKey":"stable unique request key"},"agentAllowed":true},{"name":"sports_propose","usage":"确认卡绑定实际对象、版本、名单、金额；准备后停止，等待本人明确点击","channel":"controlled-agent-run","purpose":"准备本人核对的具体确认卡","arguments":{"code":"registered-action-code","inputJson":"JSON object encoded as string"},"agentAllowed":true},{"name":"sports_delegate","usage":"简单任务直接处理；权限与对象范围只能继承或收窄，不替用户做决定","channel":"controlled-agent-run","purpose":"把必要的跨流程目标交给已授权职能助手","arguments":{"goal":"visible subgoal","agentCode":"registered-agent-code"},"agentAllowed":true},{"name":"sports_event_query_ai_constraints","usage":"仅旧登录会话调用；新 Agent 必须走能力注册表与 sports_preview","channel":"legacy-session","purpose":"读取旧资料办赛流程允许的字段、审核方式和免费约束","arguments":{},"agentAllowed":false},{"name":"sports_event_query_ai_document","usage":"组织授权由既有资料接口检查；不能以 Agent-run 令牌绕过受控执行器","channel":"legacy-session","purpose":"读取旧资料任务已授权的原文块","arguments":{"taskId":"long task id","fileIndex":"integer file index","blockLabel":"string block label"},"agentAllowed":false},{"name":"sports_event_check_ai_proposal","usage":"仅校验，不能代表创建或发布；新 Agent 走已登记动作预览","channel":"legacy-session","purpose":"校验旧办赛候选方案中的字段与玩法边界","arguments":{"proposalJson":"JSON proposal encoded as string"},"agentAllowed":false},{"name":"sports_event_query_public","usage":"仅旧登录会话用途；不暴露材料、私人资料或未公开赛事","channel":"legacy-session","purpose":"按条件分页检索已公开赛事，每页最多八场","arguments":{"text":"string search term","phase":"string phase","offset":"integer offset","project":"string project code","includeCancelled":"boolean"},"agentAllowed":false},{"name":"sports_registration_query_mine","usage":"当前本人由服务端取得，不能指定其他用户；Agent 使用已登记 registration.mine","channel":"legacy-session","purpose":"读取旧登录者本人的报名进度","arguments":{"offset":"integer offset"},"agentAllowed":false}],"transport":"authenticated-local-mcp","schemaVersion":1}'::jsonb, '{"entries":[{"code":"understand-goal","name":"明确这次目标","tools":["sports_playbook","sports_capabilities"],"actors":["platform","organizer","government","admin"],"purpose":"理解用户希望完成的任务，区分咨询、草稿、已确认办理和继续处理","procedure":["结合页面对象、当前进度和最近消息理解目标","用一句自然的话说明正在帮用户处理什么","最多先问三个真正阻塞下一步的问题，能从授权事实取得的资料不反复问"]},{"code":"material-to-draft","name":"从材料整理可核对草稿","tools":["sports_preview","sports_execute","sports_propose"],"actors":["organizer"],"workflow":"organize-event","procedure":["按文件名、页码或段落引用，明确未覆盖范围","识别日