cks":["本人资料与声明","整单名额和当前版本","本人明确确认"],"dependsOn":["registration-draft"],"capabilities":["registration.submit"]}],"title":"完成报名","actors":["platform"]},{"code":"after-event","goal":"查看正式赛果、证明与成长，并接续退款或投诉责任","steps":[{"code":"aftercare-progress","path":"/org-desk/workspace/{eventId}?task=closure","title":"查看赛后收尾","actors":["organizer"],"checks":["比赛状态","资金责任","未完投诉"],"capabilities":["event.closure"]},{"code":"aftercare-growth","path":"/portal/growth","title":"查看本人运动成长","actors":["platform"],"checks":["成长来源与真实事实","本人选择佩戴称号"],"capabilities":["growth.card","growth.equip"]},{"code":"aftercare-issue","path":"/portal/issues","title":"提交或接续问题","actors":["platform"],"checks":["问题编号","实际责任人与回复"],"capabilities":["complaint.submit","complaint.reply"]}],"title":"赛后与问题处理","actors":["platform","organizer","government"]},{"code":"government-service","goal":"按已指定的管理范围审核、协调与恢复资格","steps":[{"code":"government-scope","title":"核对主办方资格","checks":["明确分配的主办方范围","材料和协调责任"],"questions":["要处理哪家主办方？"],"capabilities":["government.qualify"]},{"code":"government-issue","path":"/government/issues","title":"协调具体问题","checks":["责任人","历史回复和当前状态"],"questions":["要接续哪一个问题编号？"],"capabilities":["complaint.handle","complaint.reply"]}],"title":"主办方审核与协调","actors":["government","admin"]}],"title":"赛事服务流程","schemaVersion":1}'::jsonb, '1cf7b9ec6dbd778216ab9341969749f8e1270b260e547b8599167605fad2b481'::character varying(64));
INSERT INTO asp_agent_version (id, agent_id, revision, model_name, instruction, budget, status, create_dept, create_by, create_time, update_by, update_time, version, tool_catalog, skill_catalog, business_map, playbook_hash) VALUES (831000000311, 831000000011, 3, 'deepseek-flash'::character varying(80), '先理解用户真正想办成什么，按本次锁定的技能目录、业务地图和实际能力带着用户推进。先查sports_playbook与当前能力，区分页面可办与助手可办；能从授权事实取得的资料不重复追问。一次优先处理一个最小阻塞项，最多补问三个必要问题，说明为什么需要与补完后会做什么。对新人自然欢迎，对担心和失败先接住具体困难，不夸大成就、不空泛鼓励。引用材料的真实位置和覆盖范围；冲突明确补问，不能猜编号、日期、费用或政府背书。缺权限或能力未开放时说明实际边界，给本人能继续的人工入口。涉及发布、报名及重要变更，用当前版本准备确认卡后停下；真实资金、政府审核、正式结果和荣誉由责任人办理。成功只依据真实业务回执。用户可見业务步骤、补充与回执需要可恢复；不输出或保存隐藏思考、凭据或未经授权的材料。最终答复使用reply与blocks的JSON对象，提供引导、必要问题、待办清单及已登记的下一步入口，避免演示口号和技术配置术语。 接续时先读取sports_recovery，不重放已成功办理。跨职能委派后读取sports_children，分清待补充、失败、待本人确认和已返回的真实结果；不得将创建子任务当作完成。服务端决定身份、预算和原请求键。'::text, '{"maxDepth":3,"maxChildren":4,"activeSeconds":300,"maxTokensTotal":120000,"maxToolsPerTurn":30,"maxTokensPerTurn":30000}'::jsonb, 'active'::character varying(32), NULL, NULL, CURRENT_TIMESTAMP, NULL, CURRENT_TIMESTAMP, 0, '{"entries":[{"name":"sports_playbook","usage":"开始办理及授权变化后先读取；这是引导资料，不能扩大操作权限","channel":"controlled-agent-run","purpose":"读取本次运行锁定的技能与业务地图，以及当前角色实际可用的页面/Agent能力","arguments":{},"agentAllowed":true},{"name":"sports_capabilities","usage":"选择实际工具动作之前读取，不把页面能力当Agent授权","channel":"controlled-agent-run","purpose":"查询本人当前已开放的Agent能力","arguments":{},"agentAllowed":true},{"name":"sports_preview","usage":"编号来自本人已授权查询或本人明确提供，不猜编号","channel":"controlled-agent-run","purpose":"核对真实对象、缺项和当前版本","arguments":{"code":"registered-action-code","inputJson":"JSON object encoded as string"},"agentAllowed":true},{"name":"sports_execute","usage":"同一办理断线重试沿用原参数与原编号；资金、审核与正式结果不得代确认","channel":"controlled-agent-run","purpose":"执行已开放、无需本人确认的授权动作","arguments":{"code":"registered-action-code","inputJson":"JSON object encoded as string","requestKey":"stable unique request key"},"agentAllowed":true},{"name":"sports_propose","usage":"确认卡绑定实际对象、版本、名单、金额；准备后停止，等待本人明确点击","channel":"controlled-agent-run","purpose":"准备本人核对的具体确认卡","arguments":{"code":"registered-action-code","inputJson":"JSON object encoded as string"},"agentAllowed":true},{"name":"sports_delegate","usage":"简单任务直接处理；权限与对象范围只能继承或收窄，不替用户做决定","channel":"controlled-agent-run","purpose":"把必要的跨流程目标交给已授权职能助手","arguments":{"goal":"visible subgoal","agentCode":"registered-agent-code"},"agentAllowed":true},{"name":"sports_children","usage":"委派后先核对实际结果；等待中的子任务不当作完成，待确认内容由本人在对应任务确认","channel":"controlled-agent-run","purpose":"读取本任务直接委派的可见结果、失败或本人确认状态","arguments":{"waitSeconds":"integer 0..10"},"agentAllowed":true},{"name":"sports_recovery","usage":"接续前先读取；成功动作不重放，历史事实须核对当前对象权限与版本","channel":"controlled-agent-run","purpose":"恢复当前仍授权的办理回执、对象版本与原请求编号","arguments":{},"agentAllowed":true},{"name":"sports_event_query_ai_constraints","usage":"仅旧登录会话调用；新 Agent 必须走能力注册表与 sports_preview","channel":"legacy-session","purpose":"读取旧资料办赛流程允许的字段、审核方式和免费约束","arguments":{},"agentAllowed":false},{"name":"sports_event_query_ai_document","usage":"组织授权由既有资料接口检查；不能以 Agent-run 令牌绕过受控执行器","channel":"legacy-session","purpose":"读取旧资料任务已授权的原文块","arguments":{"taskId":"long task id","fileIndex":"integer file index","blockLabel":"string block label"},"agentAllowed":false},{"name":"sports_event_check_ai_proposal","usage":"仅校验，不能代表创建或发布；新 Agent 走已登记动作预览","channel":"legacy-session","purpose":"校验旧办赛候选方案中的字段与玩法边界","arguments":{"proposalJson":"JSON proposal encoded as string"},"agentAllowed":false},{"name":"sports_event_query_public","usage":"仅旧登录会话用途；不暴露材料、私人资料或未公开赛事","channel":"legacy-session","purpose":"按条件分页检索已公开赛事，每页最多八场","arguments":{"text":"string search term","phase":"string phase","offset":"integer offset","project":"string project code","includeCancelled":"boolean"},"agentAllowed":false},{"name":"sports_registration_query_mine","usage":"当前本人由服务端取得，不能指定其他用户；Agent 使用已登记 registration.mine","channel":"legacy-session","purpose":"读取旧登录者本人的报名进度","arguments":{"offset":"integer offset"},"agentAllowed":false}],"transport":"authenticated-local-mcp","schemaVersion":1}'::jsonb, '{"entries":[{"code":"understand-goal","name":"明确这次目标","tools":["sports_playbook","sports_capabilities"],"actors":["platform","organizer","government","admin"],"purpose":"理解用户希望完成的任务，区分咨询、草稿、已确认办理和继续处理","procedure":["结合页面对象、当前进度和最近消息理解目标","用一句自然的话说明正在帮用户处理什么","最多先问三个真正阻塞下一步的问题，能从授权事实取得的资料不反复问"]},{"code":"material-to-draft","name":"从材料整理可核对草稿","tools":["sports_preview","sports_execute","sports_propose"],"actors":["organizer"],"workflow":"organize-event","procedure":["按文件名、页码或段落引用，明确未覆盖范围","识别日期、地点、人数、费用、联系人等缺项与冲突","缺项向主办方补问；未经核对的安排保持待确认","选择已授权的建草稿动作，发布前交本人核对"]},{"code":"assemble-teammates","name":"陪用户完成本场集结","tools":["sports_preview","sports_execute","sports_propose"],"actors":["platform"],"workflow":"join-and-team","procedure":["先问目标赛事、比赛类型和是否已有搭档","区分长期成员与本场参赛名单，房主占一席","缺人时说明招募与自动匹配两条路径；本人接受后才进房","引导各自补资料、声明和准备，不能代队员确认"]},{"code":"registration-readiness","name":"把报名缺项拆成可完成的下一步","tools":["sports_preview","sports_propose"],"actors":["platform"],"workflow":"register-event","procedure":["核对项目、可用名额、报名管理人和队员本人资料","把当前真实缺项列为待办，优先最小阻塞项","正式提交前准备版本绑定的名单、规则和费用确认","付款申报与实际收款分别说明，只按回执解释当前状态"]},{"code":"responsible-aftercare","name":"接续比赛与问题收尾","tools":["sports_preview","sports_delegate"],"actors":["platform","organizer","government"],"workflow":"after-event","procedure":["分别核对比赛结束、资金收尾和问题处理","责任人办理正式赛果、真实收退款和投诉协调","解释历史、下一步与人工入口，不制造完成或荣誉","公开分享只使用本人已授权的名片与脱敏战绩"]},{"code":"recover-and-guide","name":"失败后接住用户继续办理","tools":["sports_playbook","sports_preview","sports_recovery","sports_children"],"actors":["platform","organizer","government","admin"],"procedure":["说明实际失败点，不把等待或HTTP成功当办理成功","保留原目标、编辑内容、问题和已成功的回执","授权或内容变化时重新核对，不能沿旧确认执行","给一个可以立即继续的选择，语气自然，避免配置术语和演示口号","先恢复当前授权的真实办理回执；委派结果分别标明完成本轮、需补充、失败或待本人确认，不把子任务创建当作业务完成"]}],"schemaVersion":1}'::jsonb, '{"code":"badminton-phase1","flows":[{"code":"organize-event","goal":"材料齐全后建立赛事，核对比赛类型、报名与费用，再由主办方明确发布","steps":[{"code":"event-draft","path":"/org-desk/events/from-docume