-- 业务目录。结构基线就位后执行一次。
-- 运动项目、比赛类型、成长规则和智能体定义。能力渠道保持迁移完成时的关闭或目录状态。
-- 重复执行会因主键冲突失败。

-- asp_sport: 4

-- asp_competition_type: 2

-- asp_growth_policy: 3

-- asp_agent: 8

-- asp_agent_version: 24

-- asp_agent_grant: 89

-- 应用账号不写迁移账本。Flyway 建表时若已有默认授权，这里收回。
DO $revoke_flyway_history$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'aisports_app') THEN
        REVOKE ALL ON TABLE flyway_schema_history FROM aisports_app;
    END IF;
END
$revoke_flyway_history$;
